import{_ as t}from"./chunks/folders.9ioZn9MV.js";import{_ as o,c as a,o as r,a2 as s}from"./chunks/framework.CIiVzG-O.js";const g=JSON.parse('{"title":"Compare folders","description":"See new, changed and missing files across two folders, filter the tree and bring both sides in sync.","frontmatter":{"title":"Compare folders","description":"See new, changed and missing files across two folders, filter the tree and bring both sides in sync."},"headers":[],"relativePath":"guide/folders.md","filePath":"guide/folders.md","lastUpdated":1793948370000}'),i={name:"guide/folders.md"};function n(l,e,h,d,c,f){return r(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="compare-folders" tabindex="-1">Compare folders <a class="header-anchor" href="#compare-folders" aria-label="Permalink to &quot;Compare folders&quot;">​</a></h1><p>When two folders should match — a working copy and a backup, an old export and a new one — comparing them one file at a time is a chore. qDiff shows the whole tree at once.</p><img src="'+t+'" alt="Two folder trees with coloured file states" class="guide-shot"><h2 id="open-two-folders" tabindex="-1">Open two folders <a class="header-anchor" href="#open-two-folders" aria-label="Permalink to &quot;Open two folders&quot;">​</a></h2><p>Drag two folders onto the window, or pick them from <strong>File → Open</strong>. Folders inside folders are compared too, so you see the complete picture.</p><h2 id="read-the-tree-at-a-glance" tabindex="-1">Read the tree at a glance <a class="header-anchor" href="#read-the-tree-at-a-glance" aria-label="Permalink to &quot;Read the tree at a glance&quot;">​</a></h2><ul><li><strong>Green</strong> — a file that only exists on one side.</li><li><strong>Orange</strong> — the name matches but the content differs.</li><li><strong>Red</strong> — a file that is missing on the other side.</li><li><strong>Grey</strong> — the two sides match.</li></ul><h2 id="only-show-what-matters" tabindex="-1">Only show what matters <a class="header-anchor" href="#only-show-what-matters" aria-label="Permalink to &quot;Only show what matters&quot;">​</a></h2><p>Use the status filters to hide everything that already matches, or type part of a name to narrow the list. You can choose a quick name-only check or have qDiff read the contents as well — useful when a backup looks right but might be out of date inside.</p><p>Even large folders open quickly, so you are not left watching a progress bar.</p><h2 id="put-things-right-from-the-list" tabindex="-1">Put things right from the list <a class="header-anchor" href="#put-things-right-from-the-list" aria-label="Permalink to &quot;Put things right from the list&quot;">​</a></h2><p>Copy a file to the other side, remove a leftover, or sync a whole group — all from the same tree. There is no need to switch back to the Finder.</p><div class="tip custom-block"><p class="custom-block-title">Fine to explore</p><p>Nothing is changed on disk until you choose an action. Browsing and filtering a comparison is completely safe.</p></div><p>Next: <a href="./projects.html">review a project before committing</a>.</p>',14)])])}const u=o(i,[["render",n]]);export{g as __pageData,u as default};
